def restart_cancelled(self):
    if not self.filename or not self.buttons["restart"].get_sensitive():
        return
    from ks_includes.print_controls import set_policy

    filename = self.filename
    socket = self._screen._ws
    enabled = int(self.restart_mesh_switch.get_active())
    self.disable_button("restart")
    self.restart_mesh_switch.set_sensitive(False)

    def current():
        return self.state == "cancelled" and self.filename == filename and self._screen._ws is socket

    def failed(message=None):
        self.restart_mesh_switch.set_sensitive(True)
        if self.state == "cancelled" and self.filename == filename:
            self.enable_button("restart")
        if message:
            self._screen.show_popup_message(str(message))

    def mesh_selected(result, *args):
        if not current() or "error" in result:
            failed(result.get("error"))
            return
        self.restart_print()

    def select_mesh():
        if not current():
            failed()
            return
        if not socket.send_method("printer.gcode.script",
                                  {"script": f"SCREEN_MESH_SELECT ENABLE={enabled}"}, mesh_selected):
            failed(_("Printer connection unavailable"))

    def policy_finished(result=None):
        if not result or "error" in result:
            failed()

    set_policy(self._screen, False, select_mesh, finished=policy_finished)

